    if len(adj) != len(adj[0]):
        is_matrix = False
    else:
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor list
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = [list(lst) for lst in adj]
        # Ensure undirected: add reverse edges if missing
        for u in range(n):
            for v in neighbors[u]:
                if u not in neighbors[v]:
                    neighbors[v].append(u)

    # Precompute degrees
    degrees = [len(neighbors[i]) for i in range(n)]

