    # Strategy 4: Welsh-Powell (degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-degrees[x], x))
        return greedy_color(order)

    # Strategy 5: Randomized DSATUR with restarts
    def dsatur_random(restarts=5):
        best_coloring = None
        best_num = float('inf')
        for _ in range(restarts):
            color = [-1] * n
            saturated = [set() for _ in range(n)]
            uncolored = set(range(n))
