            num = num_colors(color)
            if num < best_num:
                best_num = num
                best_coloring = color[:]
        return best_coloring if best_coloring is not None else greedy_color(list(range(n)))

    # Run all strategies and pick best
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last),
        ("Welsh-Powell", welsh_powell),
